def decide(self, operation: str, values: dict, row: dict) -> bool:
    inputs = {key: values[key] for key in self.policy.policy["inputs"] if key in values}
    evaluation = self.policy.check(operation, inputs, row["id"] + ":" + str(row["revision"]) + ":" + uuid.uuid4().hex)
    allowed = evaluation["value"] is True
    unknown = evaluation["value"] is None
    self.bo_policy_report(evaluation, row["id"])
    self.bo_emit("policy-check", "decision", {"operation": operation, "actor_id": values["actor_id"], "owner_id": values["owner_id"], "file_id": row["id"], "bo_check": evaluation["check_id"], "fact_revision": evaluation["fact_revision"]}, {"allowed": allowed, "decision": evaluation["decision"]})
    if unknown:
        raise BusinessError(503, "暂时无法确认访问权限")
    return allowed

