def snapshot(self):
    """Read authoritative values independently of observer events and projections."""
    with self.engine.connect() as connection:
        result = []
        for row in connection.execute(select(files)).mappings():
            count = connection.scalar(select(func.count()).select_from(grants).where(grants.c.file_id == row["id"], grants.c.active.is_(True)))
            result.append({"id": row["id"], "file_id": row["id"], "owner_id": row["owner_id"], "size": row["size"], "state": row["state"], "revision": row["revision"], "grant_count": count})
        return {"files": result}

