"""Business authorization rules; no observation dependency."""

def is_owner(context: dict, payload: dict) -> bool:
    return same_identity(payload["actor_id"], context["owner_id"])

def has_remaining(context: dict, payload: dict) -> bool:
    return context["grant_count"] > 0

def same_identity(left: str, right: str) -> bool:
    return left == right

def flag_enabled(value: bool) -> bool:
    return value

def can_access(actor_id: str, owner_id: str, grant_exists: bool, grant_active: bool) -> bool:
    """Retained V1 reference helper; production V2 uses the bound policy DAG."""
    return actor_id == owner_id or (grant_exists and grant_active)

