"""Small file-sharing service with a neutral, failure-isolated event port."""
import hashlib
import hmac
from pathlib import Path
import secrets
import threading
import uuid
from .storage import password_digest
from bo_stategraph.workflow import FileWorkflow
from bo_stategraph.policy_runner import FilePolicy

class BusinessError(Exception):
    def __init__(self, status: int, message: str):
        super().__init__(message)
        self.status, self.message = status, message

class FileService:
    def __init__(self, root: Path, store, bo_sink=None):
        self.root, self.store, self.bo_sink = Path(root), store, bo_sink
        self.workflow = FileWorkflow(root)
        self.policy = FilePolicy(root)
        self.bo_policy_sink = None
        self.blobs = store.root / "uploads"
        self.blobs.mkdir(exist_ok=True)
        self.sessions = {}
        self.lock = threading.RLock()

    def bo_emit(self, node: str, phase: str, inputs: dict, outputs: dict, row=None, transition=None):
        if self.bo_sink:
            try:
                self.bo_sink(node, phase, inputs, outputs, row, transition)
            except Exception:
                pass

    def bo_policy_report(self, evaluation: dict, file_id: str):
        if self.bo_policy_sink:
            try:
                self.bo_policy_sink(evaluation, file_id)
            except Exception:
                pass

    def decide(self, operation: str, values: dict, row: dict) -> bool:
        inputs = {key: values[key] for key in self.policy.policy["inputs"] if key in values}
        evaluation = self.policy.check(operation, inputs, row["id"] + ":" + str(row["revision"]) + ":" + uuid.uuid4().hex)
        allowed = evaluation["value"] is True
        unknown = evaluation["value"] is None
        self.bo_policy_report(evaluation, row["id"])
        self.bo_emit("policy-check", "decision", {"operation": operation, "actor_id": values["actor_id"], "owner_id": values["owner_id"], "file_id": row["id"], "bo_check": evaluation["check_id"], "fact_revision": evaluation["fact_revision"]}, {"allowed": allowed, "decision": evaluation["decision"]})
        if unknown:
            raise BusinessError(503, "暂时无法确认访问权限")
        return allowed

    def login(self, actor_id: str, password: str):
        user = self.store.user(actor_id)
        allowed = bool(user and hmac.compare_digest(user["password_hash"], password_digest(actor_id, password)))
        self.bo_emit("login", "return", {"actor_id": actor_id}, {"allowed": allowed})
        if not allowed:
            raise BusinessError(401, "账号或密码不正确")
        token = secrets.token_urlsafe(32)
        with self.lock:
            self.sessions[token] = actor_id
        return token, {"id": user["id"], "name": user["name"]}

    def actor(self, token: str):
        with self.lock:
            actor_id = self.sessions.get(token)
        if not actor_id:
            raise BusinessError(401, "请先登录")
        return actor_id

    def logout(self, token: str):
        with self.lock:
            actor_id = self.sessions.pop(token, "")
        self.bo_emit("logout", "return", {"actor_id": actor_id}, {"signed_out": True})

    def users(self, actor_id: str):
        rows = self.store.list_users()
        self.bo_emit("users", "return", {"actor_id": actor_id}, {"count": len(rows)})
        return rows

    def upload(self, actor_id: str, filename: str, content: bytes):
        name = Path(filename.replace("\\", "/")).name.strip()
        if not name or len(name) > 180 or any(ord(char) < 32 for char in name):
            raise BusinessError(400, "文件名无效")
        if len(content) > 10 * 1024 * 1024:
            raise BusinessError(413, "演示文件不能超过 10 MB")
        ident = uuid.uuid4().hex
        row = {"id": ident, "name": name, "size": len(content), "owner_id": actor_id, "storage_key": ident, "state": self.workflow.machine["initial"], "revision": 1}
        path = self.blobs / ident
        path.write_bytes(content)
        try:
            self.store.add_file(row)
        except Exception:
            path.unlink(missing_ok=True)
            raise
        self.bo_emit("upload", "commit", {"actor_id": actor_id, "filename": name, "size": len(content)}, {"file_id": ident, "owner_id": actor_id, "state": row["state"], "revision": 1}, row)
        return self.public_file(row)

    def public_file(self, row: dict):
        user = self.store.user(row["owner_id"])
        return {key: row[key] for key in ("id", "name", "size", "owner_id", "state", "revision")} | {"owner_name": user["name"]}

    def list_files(self, actor_id: str):
        rows = self.store.list_files(actor_id)
        result = [self.public_file(row) for row in rows]
        for item in result:
            if item["owner_id"] == actor_id:
                item["recipients"] = self.store.active_recipients(item["id"])
        self.bo_emit("list", "return", {"actor_id": actor_id}, {"count": len(result), "file_ids": [row["id"] for row in result]})
        return result

    def read_access(self, actor_id: str, file_id: str):
        row = self.store.file(file_id)
        if row is None:
            raise BusinessError(404, "文件不存在")
        grant = self.store.grant(file_id, actor_id)
        values = {"actor_id": actor_id, "file_id": file_id, "owner_id": row["owner_id"], "grant_exists": grant is not None, "grant_active": bool(grant and grant["active"])}
        return row, values

    def details(self, actor_id: str, file_id: str):
        row, values = self.read_access(actor_id, file_id)
        allowed = self.decide("view", values, row)
        self.bo_emit("view-policy", "decision", values, {"allowed": allowed})
        if not allowed:
            raise BusinessError(403, "你没有查看这个文件的权限")
        result = self.public_file(row)
        self.bo_emit("view", "return", {"actor_id": actor_id, "file_id": file_id}, {"name": row["name"], "size": row["size"], "owner_id": row["owner_id"]})
        return result

    def download(self, actor_id: str, file_id: str):
        row, values = self.read_access(actor_id, file_id)
        allowed = self.decide("download", values, row)
        self.bo_emit("download-policy", "decision", values, {"allowed": allowed})
        if not allowed:
            self.bo_emit("denied", "return", {"actor_id": actor_id, "file_id": file_id}, {"allowed": False})
            raise BusinessError(403, "你没有下载这个文件的权限")
        content = (self.blobs / row["storage_key"]).read_bytes()
        self.bo_emit("download", "return", {"actor_id": actor_id, "file_id": file_id}, {"size": len(content), "sha256": hashlib.sha256(content).hexdigest()})
        return row["name"], content

    def share(self, actor_id: str, file_id: str, recipient_id: str):
        with self.lock:
            row = self.store.file(file_id)
            if row is None:
                raise BusinessError(404, "文件不存在")
            allowed = self.decide("share", {"actor_id": actor_id, "owner_id": row["owner_id"]}, row)
            self.bo_emit("share-policy", "decision", {"actor_id": actor_id, "file_id": file_id, "owner_id": row["owner_id"], "recipient_id": recipient_id}, {"allowed": allowed})
            if not allowed:
                raise BusinessError(403, "只有文件所有者可以共享")
            if recipient_id == actor_id or not self.store.user(recipient_id):
                raise BusinessError(400, "请选择另一位已有用户")
            before = next(item for item in self.store.snapshot()["files"] if item["id"] == file_id)
            transition = self.workflow.share(row, actor_id, recipient_id, before["grant_count"])
            self.store.share_file(file_id, recipient_id, transition["state"])
            current = self.store.file(file_id)
            self.bo_emit("share", "commit", {"actor_id": actor_id, "file_id": file_id, "recipient_id": recipient_id}, {"state": current["state"], "revision": current["revision"], "active": True, "before_state": row["state"], "event": transition["event"], "guards": transition["guards"]}, current, {**transition, "source": row["state"]})
            return {"file_id": file_id, "recipient_id": recipient_id, "active": True}

    def revoke(self, actor_id: str, file_id: str, recipient_id: str):
        with self.lock:
            row = self.store.file(file_id)
            if row is None:
                raise BusinessError(404, "文件不存在")
            allowed = self.decide("revoke", {"actor_id": actor_id, "owner_id": row["owner_id"]}, row)
            self.bo_emit("revoke-policy", "decision", {"actor_id": actor_id, "file_id": file_id, "owner_id": row["owner_id"], "recipient_id": recipient_id}, {"allowed": allowed})
            if not allowed:
                raise BusinessError(403, "只有文件所有者可以取消共享")
            if not self.store.user(recipient_id):
                raise BusinessError(400, "请选择已有接收者")
            grant = self.store.grant(file_id, recipient_id)
            before = next(item for item in self.store.snapshot()["files"] if item["id"] == file_id)
            remaining = before["grant_count"] - (1 if grant and grant["active"] else 0)
            transition = self.workflow.revoke(row, actor_id, recipient_id, remaining)
            self.store.revoke_file(file_id, recipient_id, transition["state"])
            current = self.store.file(file_id)
            self.bo_emit("revoke", "commit", {"actor_id": actor_id, "file_id": file_id, "recipient_id": recipient_id}, {"state": current["state"], "revision": current["revision"], "active": False, "before_state": row["state"], "event": transition["event"], "guards": transition["guards"]}, current, {**transition, "source": row["state"]})
            return {"file_id": file_id, "recipient_id": recipient_id, "active": False}

