sources.bo_stategraph/execution_contract.py:
"""Check an inline activity configuration against its state graph and actual journal.

This protocol supports one invocation per declared activity in each run, integer
capacity, atomic allocation, completion and ALL join. It does not infer hidden calls.
"""

from copy import deepcopy

TERMINAL = {"succeeded", "rejected", "failed", "cancelled"}


def validate_execution_graph(model):
    """Validate activity, join, and resource declarations within the same state graph."""
    spec = model.get("machine", {}).get("execution")
    if not spec:
        return {"valid": True, "applicable": False}
    if spec.get("schema") != "activity-graph/v1":
        raise ValueError("unsupported activity configuration schema")
    chart = model["machine"]
    nodes = {n["id"]: n for n in model["nodes"]}
    if spec["within"] not in chart["values"] or spec["parent"] not in nodes:
        raise ValueError("execution scope missing")
    activities = {a["id"]: a for a in spec["activities"]}
    resources = {r["id"]: r for r in spec["resources"]}
    join = spec["join"]
    if (
        not activities
        or len(activities) != len(spec["activities"])
        or len(resources) != len(spec["resources"])
    ):
        raise ValueError("duplicate or missing activity/resource IDs")
    if set(activities) & set(resources) or join["id"] in {*activities, *resources}:
        raise ValueError("execution identities overlap")
    if (
        join["policy"] != "all"
        or len(set(join["requires"])) != len(join["requires"])
        or set(join["requires"]) != set(activities)
    ):
        raise ValueError("ALL join must include every declared activity")
    if set(spec["activity_states"]) != {"pending", "waiting", "running", *TERMINAL}:
        raise ValueError("incomplete activity states")
    for r in resources.values():
        if (
            r.get("scope") != "run"
            or type(r["min"]) is not int
            or type(r["max"]) is not int
            or not 0 < r["min"] <= r["max"]
        ):
            raise ValueError("unsupported resource scope or capacity bounds")
    expected = set()
    for aid, a in activities.items():
        if not a["requires"] or set(a["requires"]) - set(resources):
            raise ValueError("undefined resource dependency")
        for rid, units in a["requires"].items():
            if type(units) is not int or units <= 0 or units > resources[rid]["min"]:
                raise ValueError("activity cannot start at minimum capacity")
            expected.add((rid, aid, "resource", units))
        expected.add((aid, join["id"], "join", None))
        if nodes.get(aid, {}).get("source") != a["source"]:
            raise ValueError("activity source and graph source differ: " + aid)
    for key, role in (
        [(a, "activity") for a in activities]
        + [(r, "resource") for r in resources]
        + [(join["id"], "join")]
    ):
        n = nodes.get(key, {})
        if n.get("parent") != spec["parent"] or n.get("execution_role") != role:
            raise ValueError(
                "activity configuration must be represented by the original inline node: " + key
            )
    actual = {
        (e["from"], e["to"], e["type"], e.get("units"))
        for e in model["edges"]
        if e["type"] in ("resource", "join")
    }
    if actual != expected:
        raise ValueError("inline resource/join edges differ from executable declaration")
    if model.get("worknet"):
        raise ValueError("integrated activity model must not add a separate worknet projection")
    guarded = [t for t in chart["transitions"] if t["dest"] in join["success_states"]]
    if not guarded:
        raise ValueError("missing lifecycle completion transition")
    for t in guarded:
        conditions = t.get("conditions", [])
        conditions = [conditions] if isinstance(conditions, str) else conditions
        if join["guard"] not in conditions:
            raise ValueError("lifecycle can bypass activity completion")
    return {"valid": True, "activities": len(activities), "resources": len(resources)}


def validate_configuration(model, snapshot):
    """Check a runtime activity/resource configuration against its declared capacities and states."""
    spec = model["machine"]["execution"]
    activities = {a["id"]: a for a in spec["activities"]}
    resources = {r["id"]: r for r in spec["resources"]}
    join = spec["join"]
    if (
        not isinstance(snapshot.get("attempt"), str)
        or not snapshot["attempt"]
        or type(snapshot.get("param_version")) is not int
        or snapshot["param_version"] < 1
    ):
        raise ValueError("missing execution instance identity")
    if set(snapshot.get("activities", {})) != set(activities) or set(
        snapshot.get("resources", {})
    ) != set(resources):
        raise ValueError("execution instance omits declared internal states")
    initial_resources = {}
    for rid, r in resources.items():
        capacity = snapshot["resources"][rid]["capacity"]
        if type(capacity) is not int or not r["min"] <= capacity <= r["max"]:
            raise ValueError("invalid capacity")
        initial_resources[rid] = {"capacity": capacity, "available": capacity, "holders": []}
    current = {
        "activities": {a: "pending" for a in activities},
        "resources": initial_resources,
        "join": {"state": "waiting", "pending": list(join["requires"])},
    }
    journal = snapshot.get("journal", [])
    if type(snapshot.get("revision")) is not int or snapshot["revision"] != len(journal):
        raise ValueError("missing execution updates")
    for seq, entry in enumerate(journal, 1):
        if entry["seq"] != seq or entry["before"] != current:
            raise ValueError("execution history is discontinuous")
        expected = deepcopy(current)
        event = entry["event"]
        aid = entry["activity"]
        states = expected["activities"]
        if event in ("wait", "start", "finish"):
            if aid not in activities:
                raise ValueError("unknown running activity")
            need = activities[aid]["requires"]
            can_start = all(expected["resources"][r]["available"] >= n for r, n in need.items())
            if event == "wait":
                if states[aid] != "pending" or can_start:
                    raise ValueError("resource wait has no missing resource")
                states[aid] = "waiting"
            elif event == "start":
                if states[aid] not in ("pending", "waiting") or not can_start:
                    raise ValueError("activity started without resource")
                for rid, n in need.items():
                    expected["resources"][rid]["available"] -= n
                    expected["resources"][rid]["holders"].append(aid)
                states[aid] = "running"
            else:
                outcome = entry["after"]["activities"].get(aid)
                if states[aid] != "running" or outcome not in {"succeeded", "rejected", "failed"}:
                    raise ValueError("completion without running activity")
                for rid, n in need.items():
                    expected["resources"][rid]["available"] += n
                    expected["resources"][rid]["holders"].remove(aid)
                states[aid] = outcome
                if all(states[a] in TERMINAL for a in join["requires"]):
                    expected["join"]["state"] = "enabled"
        elif event == "join":
            if aid != join["id"] or expected["join"]["state"] != "enabled":
                raise ValueError("join before all activities completed")
            expected["join"]["state"] = (
                "passed" if all(states[a] == "succeeded" for a in join["requires"]) else "rejected"
            )
        elif event == "abort":
            if aid != join["id"] or "running" in states.values():
                raise ValueError("abort leaves running activity/resource")
            expected["activities"] = {
                a: s if s in TERMINAL else "cancelled" for a, s in states.items()
            }
            expected["join"]["state"] = "rejected"
        else:
            raise ValueError("unknown internal state event")
        expected["join"]["pending"] = [
            a for a in join["requires"] if expected["activities"][a] not in TERMINAL
        ]
        if expected != entry["after"]:
            raise ValueError("internal state update violates declared resource or join rules")
        current = expected
    if current != {k: snapshot[k] for k in ("activities", "resources", "join")}:
        raise ValueError("current state differs from actual execution history")
    if snapshot.get("phase") in join["success_states"] and (
        current["join"]["state"] != "passed"
        or any(s != "succeeded" for s in current["activities"].values())
    ):
        raise ValueError("lifecycle advanced before this execution completed")
    return {"valid": True, "updates": len(journal)}

sources.bo_stategraph/policy/definition.py:
"""Validate a language-neutral expression DAG before binding or execution.

Predicate definitions describe functions. Expression nodes bind their parameters.
Only nodes with the same identity share a result inside one evaluation.
"""

from __future__ import annotations

import hashlib
import json
import math
import re

TYPES = {"string", "boolean", "number"}
OPERATORS = {"input", "constant", "predicate", "all", "any", "not"}
IDENTITY = re.compile(r"^[A-Za-z][A-Za-z0-9_.:-]{0,159}$")


def fingerprint(value):
    """Use portable JSON bytes to identify the complete declaration, not its label."""
    return hashlib.sha256(
        json.dumps(
            value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False
        ).encode()
    ).hexdigest()


def matches(value, kind):
    return (
        (kind == "string" and isinstance(value, str) and len(value) <= 256)
        or (kind == "boolean" and type(value) is bool)
        or (
            kind == "number"
            and type(value) in (int, float)
            and math.isfinite(value)
            and abs(value) <= 9007199254740991
        )
    )


def records(values, name, *, allow_empty=False):
    if not isinstance(values, list) or (not values and not allow_empty):
        raise ValueError(name + " must be a nonempty list")
    result = {}
    for value in values:
        if (
            not isinstance(value, dict)
            or not isinstance(value.get("id"), str)
            or not IDENTITY.fullmatch(value["id"])
        ):
            raise ValueError(name + " contains an invalid identity")
        if value["id"] in result:
            raise ValueError(name + " contains a duplicate identity: " + value["id"])
        result[value["id"]] = value
    return result


def provenance(value, name):
    refs = value.get("source_refs")
    if (
        not isinstance(refs, list)
        or not refs
        or any(not isinstance(ref, str) or not ref.strip() for ref in refs)
    ):
        raise ValueError(name + " needs conversation or existing-rule provenance")


def dependencies(node):
    if node["op"] == "predicate":
        return list(dict.fromkeys(node["arguments"].values()))
    return node.get("inputs", [])


def validate(policy, *, bound=True):
    """Reject malformed rules; return indexes and a dependency-first order.

    A draft can reserve predicate identities before source exists. It cannot pass
    the bound runtime gate. Business-flow loops are outside this expression DAG.
    """
    if not isinstance(policy, dict) or policy.get("schema") != "bo-policy/v1":
        raise ValueError("expected bo-policy/v1")
    if not isinstance(policy.get("revision"), str) or not policy["revision"].strip():
        raise ValueError("policy revision is required")
    if (
        not isinstance(policy.get("stage"), str)
        or policy.get("stage") not in {"draft", "bound"}
        or (bound and policy["stage"] != "bound")
    ):
        raise ValueError("runtime policy must be bound")
    inputs = policy.get("inputs")
    if not isinstance(inputs, dict) or any(
        not isinstance(k, str)
        or not IDENTITY.fullmatch(k)
        or not isinstance(v, str)
        or v not in TYPES
        for k, v in inputs.items()
    ):
        raise ValueError("policy inputs need named portable scalar types")
    predicates = records(policy.get("predicates"), "predicates", allow_empty=True)
    nodes = records(policy.get("nodes"), "policy nodes")
    operations = records(policy.get("operations"), "policy operations")
    if len(nodes) > 4096:
        raise ValueError("policy expression budget exceeded (4096 nodes)")
    for pred in predicates.values():
        provenance(pred, pred["id"])
        parameters = pred.get("parameters")
        if not isinstance(parameters, dict) or any(
            not isinstance(k, str)
            or not IDENTITY.fullmatch(k)
            or not isinstance(v, str)
            or v not in TYPES
            for k, v in parameters.items()
        ):
            raise ValueError("invalid predicate parameters: " + pred["id"])
        source = pred.get("source")
        if bound or source is not None:
            if (
                not isinstance(source, dict)
                or set(source) != {"path", "symbol"}
                or not all(isinstance(v, str) and v.strip() for v in source.values())
                or source["path"].startswith(("/", "\\"))
                or ":" in source["path"]
                or ".." in source["path"].replace("\\", "/").split("/")
            ):
                raise ValueError(
                    "predicate needs a project-relative source function: " + pred["id"]
                )
    output_types = {}
    used_predicates = set()
    for node in nodes.values():
        provenance(node, node["id"])
        op = node.get("op")
        if not isinstance(op, str) or op not in OPERATORS:
            raise ValueError("unsupported policy operator: " + str(op))
        fields = {"id", "op", "label", "summary", "source_refs"}
        fields |= (
            {"name"}
            if op == "input"
            else (
                {"value", "type"}
                if op == "constant"
                else {"predicate", "arguments"} if op == "predicate" else {"inputs"}
            )
        )
        if set(node) - fields:
            raise ValueError("unknown policy node fields: " + node["id"])
        if op == "input":
            if not isinstance(node.get("name"), str) or node.get("name") not in inputs:
                raise ValueError("undefined policy input: " + node["id"])
            output_types[node["id"]] = inputs[node["name"]]
        elif op == "constant":
            if (
                not isinstance(node.get("type"), str)
                or node.get("type") not in TYPES
                or not matches(node.get("value"), node["type"])
            ):
                raise ValueError("constant type differs: " + node["id"])
            output_types[node["id"]] = node["type"]
        elif op == "predicate":
            pred = (
                predicates.get(node.get("predicate"))
                if isinstance(node.get("predicate"), str)
                else None
            )
            args = node.get("arguments")
            if (
                not pred
                or not isinstance(args, dict)
                or set(args) != set(pred["parameters"])
                or any(not isinstance(ref, str) for ref in args.values())
            ):
                raise ValueError("predicate argument names differ: " + node["id"])
            used_predicates.add(pred["id"])
            output_types[node["id"]] = "boolean"
        else:
            refs = node.get("inputs")
            if (
                not isinstance(refs, list)
                or not refs
                or any(not isinstance(r, str) for r in refs)
                or len(set(refs)) != len(refs)
                or (op == "not" and len(refs) != 1)
            ):
                raise ValueError("invalid operator arity: " + node["id"])
            output_types[node["id"]] = "boolean"
    if used_predicates != set(predicates):
        raise ValueError("unreferenced predicate definitions")
    order, visiting, done = [], set(), set()

    def visit(ident):
        if len(visiting) >= 128:
            raise ValueError("policy dependency depth budget exceeded (128)")
        if not isinstance(ident, str) or ident not in nodes:
            raise ValueError("dangling policy dependency: " + str(ident))
        if ident in visiting:
            raise ValueError("policy expression cycle: " + ident)
        if ident in done:
            return
        visiting.add(ident)
        node = nodes[ident]
        for dependency in dependencies(node):
            visit(dependency)
        if node["op"] in {"all", "any", "not"} and any(
            output_types[r] != "boolean" for r in node["inputs"]
        ):
            raise ValueError("logical operator needs Boolean expressions: " + ident)
        if node["op"] == "predicate":
            pred = predicates[node["predicate"]]
            if any(
                output_types[r] != pred["parameters"][arg] for arg, r in node["arguments"].items()
            ):
                raise ValueError("predicate argument types differ: " + ident)
        visiting.remove(ident)
        done.add(ident)
        order.append(ident)

    for operation in operations.values():
        provenance(operation, operation["id"])
        if bound and (not operation.get("business_nodes") or not operation.get("cases")):
            raise ValueError(
                "bound operation needs business nodes and verification cases: " + operation["id"]
            )
        for field in ("business_nodes", "cases"):
            values = operation.get(field, [])
            if (
                not isinstance(values, list)
                or any(not isinstance(v, str) or not v for v in values)
                or len(values) != len(set(values))
            ):
                raise ValueError("invalid operation " + field)
        visit(operation.get("root"))
        if output_types[operation["root"]] != "boolean":
            raise ValueError("operation root must produce a Boolean decision")
    if done != set(nodes):
        raise ValueError("unreachable policy expressions: " + ", ".join(sorted(set(nodes) - done)))
    return {
        "nodes": nodes,
        "predicates": predicates,
        "operations": operations,
        "order": order,
        "types": output_types,
    }

sources.bo_stategraph/policy/projection.py:
"""Project shared expressions and implementation links into the existing graph."""

from copy import deepcopy

from .definition import validate, dependencies

ORIGIN = "policy-definition"
PREFIX = "policy:"


def elements(policy, base_nodes, *, bound=True):
    """Retain one canonical node per expression, regardless of permission fan-out."""
    index = validate(policy, bound=bound)
    known = {node["id"]: node for node in base_nodes}
    group = {
        "id": PREFIX + "network",
        "kind": "decision",
        "layer": "predicate",
        "label": "Rules",
        "summary": "Rules",
        "origin": ORIGIN,
        "capture": {"in": {}, "out": {}},
    }
    nodes, edges = [group], []

    def edge(ident, source, target, kind, label):
        edges.append(
            {
                "id": PREFIX + ident,
                "from": source,
                "to": target,
                "type": kind,
                "label": label,
                "origin": ORIGIN,
                "evidence": "policy declaration",
                "evidence_kind": "conceptual",
                **({"code_relation": "maps"} if kind == "maps" else {}),
            }
        )

    for item in index["nodes"].values():
        ident, op = item["id"], item["op"]
        inputs = {"bo_check": "string", "bo_basis": "string"}
        node = {
            "id": PREFIX + ident,
            "kind": "data" if op in {"input", "constant"} else "decision",
            "layer": "predicate",
            "parent": group["id"],
            "label": (
                {"all": "AND · ", "any": "OR · ", "not": "NOT · "}.get(op, "")
                + item.get("label", ident)
            ),
            "summary": item.get("summary", item.get("label", ident)),
            "origin": ORIGIN,
            "policy_node": ident,
            "operator": op,
            "source_refs": item["source_refs"],
            "capture": {"in": inputs, "out": {"value": index["types"][ident], "status": "string"}},
            "capture_metadata": {"in": ["bo_check", "bo_basis"], "out": ["status"]},
        }
        if op == "predicate":
            pred = index["predicates"][item["predicate"]]
            inputs.update(pred["parameters"])
            if pred.get("source"):
                node["source"] = deepcopy(pred["source"])
                anchor = pred.get("implementation_node")
                # Reuse a physical function already mapped elsewhere in the graph.
                matches = [
                    n
                    for n in base_nodes
                    if n.get("kind") == "function" and n.get("source") == pred["source"]
                ]
                if anchor:
                    if anchor not in known or known[anchor].get("source") != pred["source"]:
                        raise ValueError("policy implementation node differs from source")
                elif len(matches) == 1:
                    anchor = matches[0]["id"]
                else:
                    anchor = PREFIX + "function:" + pred["id"]
                    if not any(n["id"] == anchor for n in nodes):
                        nodes.append(
                            {
                                "id": anchor,
                                "kind": "function",
                                "code_role": "function",
                                "layer": "program",
                                "label": pred["source"]["symbol"],
                                "summary": "Native rule predicate",
                                "source": deepcopy(pred["source"]),
                                "origin": ORIGIN,
                                "capture": {"in": {}, "out": {}},
                            }
                        )
                edge("mapping:" + ident, node["id"], anchor, "maps", "Implemented by")
        nodes.append(node)
        edge("contains:" + ident, group["id"], node["id"], "contains", "Rule expression")
        for offset, reference in enumerate(dependencies(item)):
            edge(
                "dependency:" + ident + ":" + str(offset),
                PREFIX + reference,
                node["id"],
                "data" if op == "predicate" else "guard",
                (
                    ", ".join(k for k, ref in item.get("arguments", {}).items() if ref == reference)
                    if op == "predicate"
                    else op
                ),
            )
    for operation in index["operations"].values():
        for target in operation.get("business_nodes", []):
            if target not in known:
                raise ValueError("policy operation has no business anchor: " + target)
            edge(
                "operation:" + operation["id"] + ":" + target,
                PREFIX + operation["root"],
                target,
                "guard",
                "Requires",
            )
    return nodes, edges


def project(model, *, bound=True):
    """Replace only generated policy elements; preserve all other identities/layout data."""
    result = deepcopy(model)
    if not model.get("policy"):
        return result
    base = [node for node in model["nodes"] if node.get("origin") != ORIGIN]
    nodes, edges = elements(model["policy"], base, bound=bound)
    previous = {n["id"]: n for n in model["nodes"] if n.get("origin") == ORIGIN}
    for node in nodes:
        old = previous.get(node["id"], {})
        if old.get("source") == node.get("source") and "code_evidence" in old:
            node["code_evidence"] = deepcopy(old["code_evidence"])
    base_ids = {node["id"] for node in base}
    if base_ids.intersection(node["id"] for node in nodes):
        raise ValueError("policy projection identity collides with project nodes")
    result["nodes"] = base + nodes
    result["edges"] = [
        edge for edge in model.get("edges", []) if edge.get("origin") != ORIGIN
    ] + edges
    # Other projectors retain their own elements. Preserve the existing order
    # so composing policy/data refreshes cannot alternate the model's hash.
    for name in ("nodes", "edges"):
        order = {item["id"]: position for position, item in enumerate(model.get(name, []))}
        result[name].sort(key=lambda item: order.get(item["id"], len(order)))
    ids = [node["id"] for node in result["nodes"]]
    edge_ids = [edge["id"] for edge in result["edges"]]
    if len(ids) != len(set(ids)) or len(edge_ids) != len(set(edge_ids)):
        raise ValueError("policy projection creates duplicate identities")
    return result


def projection_errors(model, *, bound=True):
    if not model.get("policy"):
        orphaned = any(node.get("origin") == ORIGIN for node in model.get("nodes", []))
        orphaned |= any(
            edge.get("origin") == ORIGIN or edge.get("type") == "maps"
            for edge in model.get("edges", [])
        )
        return ["policy elements require a valid policy declaration"] if orphaned else []
    try:
        expected = project(model, bound=bound)
        actual_nodes = {n["id"]: n for n in model["nodes"] if n.get("origin") == ORIGIN}
        actual_edges = {e["id"]: e for e in model["edges"] if e.get("origin") == ORIGIN}
        expected_nodes = {n["id"]: n for n in expected["nodes"] if n.get("origin") == ORIGIN}
        expected_edges = {e["id"]: e for e in expected["edges"] if e.get("origin") == ORIGIN}
        if any(
            edge.get("type") == "maps" and expected_edges.get(edge["id"]) != edge
            for edge in model.get("edges", [])
        ):
            return ["maps relation is outside the exact policy projection"]
        return (
            []
            if actual_nodes == expected_nodes and actual_edges == expected_edges
            else ["policy graph projection is missing, changed or stale"]
        )
    except (ValueError, KeyError, TypeError) as exc:
        return [str(exc)]

sources.bo_stategraph/policy/runtime.py:
"""Optional native rule execution; the observer never calls it to invent facts.

The application explicitly supplies predicate callables and a request fact basis.
There is no eval(), dynamic import, database access or process-global result cache.
"""

from __future__ import annotations

import inspect
import uuid
from copy import deepcopy

from .definition import validate, fingerprint, matches
from .bindings import callable_binding


def combine(op, values):
    """Three-valued composition; predicate errors remain separate diagnostics."""
    if op == "not":
        return None if values[0] is None else not values[0]
    decisive = False if op == "all" else True
    if any(value is decisive for value in values):
        return decisive
    if any(value is None for value in values):
        return None
    return not decisive


def evaluate(
    policy, operation, inputs, callbacks, *, fact_revision, source_root, check_id=None, on_step=None
):
    """Evaluate one operation, sharing identical nodes only within this check.

    A change of input or fact revision requires a new check. Callers decide what
    business action to take; unknown/error evidence never becomes a fabricated deny.
    """
    index = validate(policy)
    if not isinstance(operation, str) or operation not in index["operations"]:
        raise ValueError("unknown policy operation")
    if not isinstance(fact_revision, str) or not fact_revision:
        raise ValueError("a fact revision or explicit request-basis identity is required")
    if not isinstance(inputs, dict) or set(inputs) - set(policy["inputs"]):
        raise ValueError("undeclared policy inputs")
    for key, value in inputs.items():
        if not matches(value, policy["inputs"][key]):
            raise ValueError("policy input type differs: " + key)
    inputs = deepcopy(inputs)
    bindings = {}
    for pred in index["predicates"].values():
        callback = callbacks.get(pred["id"])
        if not callable(callback):
            raise ValueError("missing native predicate: " + pred["id"])
        try:
            inspect.signature(callback).bind(**{name: None for name in pred["parameters"]})
        except (ValueError, TypeError) as exc:
            raise ValueError("native predicate signature differs: " + pred["id"]) from exc
        bindings[pred["id"]] = callable_binding(callback, pred["source"], source_root)
    check_id = check_id or uuid.uuid4().hex
    if not isinstance(check_id, str) or not check_id:
        raise ValueError("invalid check identity")
    cache, trace, diagnostics = {}, [], []

    def compute(ident):
        if ident in cache:
            return cache[ident]
        node = index["nodes"][ident]
        op, used, skipped, arguments = node["op"], [], [], {}
        status = "completed"
        if op == "input":
            value = inputs.get(node["name"])
            if node["name"] not in inputs:
                status = "unknown"
        elif op == "constant":
            value = node["value"]
        elif op == "predicate":
            for argument, reference in node["arguments"].items():
                arguments[argument] = compute(reference)
                if reference not in used:
                    used.append(reference)
            if any(value is None for value in arguments.values()):
                value, status = None, "unknown"
            else:
                try:
                    value = callbacks[node["predicate"]](**arguments)
                    if value is not None and type(value) is not bool:
                        raise ValueError("predicate did not return Boolean or unknown")
                    status = "unknown" if value is None else "completed"
                except Exception as exc:
                    value, status = None, "error"
                    diagnostics.append({"node": ident, "error": type(exc).__name__})
        else:
            values = []
            for offset, reference in enumerate(node["inputs"]):
                values.append(compute(reference))
                used.append(reference)
                if (op == "all" and values[-1] is False) or (op == "any" and values[-1] is True):
                    skipped = node["inputs"][offset + 1 :]
                    break
            value = combine(op, values)
            status = "unknown" if value is None else "completed"
        step = {
            "node": ident,
            "value": value,
            "status": status,
            "arguments": arguments,
            "used": used,
            "skipped": skipped,
        }
        cache[ident] = value
        trace.append(step)
        if on_step:
            try:
                on_step(deepcopy(step))
            except Exception:
                # Observation transport failures cannot change a business result.
                diagnostics.append({"node": ident, "error": "observation_sink_failed"})
        return value

    root = index["operations"][operation]["root"]
    value = compute(root)
    return {
        "schema": "bo-policy-evaluation/v1",
        "policy_revision": policy["revision"],
        "policy_hash": fingerprint(policy),
        "check_id": check_id,
        "fact_revision": fact_revision,
        "operation": operation,
        "inputs": deepcopy(inputs),
        "bindings": bindings,
        "root": root,
        "value": value,
        "decision": "allow" if value is True else "deny" if value is False else "unknown",
        "trace": trace,
        "diagnostics": diagnostics,
    }

sources.bo_stategraph/policy_runner.py:
"""Native shared-rule execution, independent of the observer and Web service."""
import json
from pathlib import Path
from .policy.runtime import evaluate
from app.policy import same_identity, flag_enabled

class FilePolicy:
    def __init__(self, project_root: Path):
        self.policy = json.loads((Path(project_root) / "bo_stategraph/project.json").read_text(encoding="utf-8"))["model"]["policy"]
        self.source_root = Path(__file__).resolve().parents[1]
        self.callbacks = {"same_identity": same_identity, "flag_enabled": flag_enabled}

    def check(self, operation: str, inputs: dict, fact_revision: str):
        return evaluate(self.policy, operation, inputs, self.callbacks, fact_revision=fact_revision, source_root=self.source_root)

