"""Project-local executor using the canonical flat-state runtime."""
import json
from pathlib import Path
from .bo_executor import BOExecutor
from app.policy import is_owner, has_remaining

class FileWorkflow:
    def __init__(self, root: Path):
        self.machine = json.loads((Path(root) / "bo_stategraph/project.json").read_text(encoding="utf-8"))["model"]["machine"]
        self.executor = BOExecutor(self.machine, {"is_owner": is_owner, "has_remaining": has_remaining})

    def share(self, row: dict, actor_id: str, recipient_id: str, grant_count: int):
        context = {"file_id": row["id"], "owner_id": row["owner_id"], "size": row["size"], "grant_count": grant_count}
        return self.executor.step(row["state"], "share", context, {"actor_id": actor_id, "recipient_id": recipient_id})

    def revoke(self, row: dict, actor_id: str, recipient_id: str, remaining_count: int):
        context = {"file_id": row["id"], "owner_id": row["owner_id"], "size": row["size"], "grant_count": remaining_count}
        return self.executor.step(row["state"], "revoke", context, {"actor_id": actor_id, "recipient_id": recipient_id})

