sources.integrations/bo_runtime.py:
"""Optional observation wiring; business methods never import this module."""
from functools import wraps
from collections import deque, OrderedDict
from copy import deepcopy
import json
from pathlib import Path
import threading
from bo_observer.adapters.python.bo_probe import BOProbe
from bo_observer.data.runtime import BODataRuntime
from bo_observer.observation.observation_scope import bo_internal
from bo_observer.service import GraphSession
from view_preferences import Preferences
from bo_observer.policy.recording import record_evaluation

class BOFileSession(GraphSession):
    """Use the public query/export core with actual database-backed snapshots."""
    def __init__(self, root, store):
        self.bo_store = store
        super().__init__(root)
        discovery = json.loads((Path(root) / "discovery.json").read_text(encoding="utf-8"))
        self.bo_layout_id = discovery["layout_id"]
        self.preferences = Preferences(root, self.bo_layout_id)

    def bo_machine(self):
        with bo_internal():
            rows = self.bo_store.snapshot()["files"]
        configurations = [{"attempt": row["id"], "phase": row["state"], "state_revision": row["revision"], "run_build_id": self.manifest["build_id"], "source_status": self.binding()["status"], "context": {key: row[key] for key in self.model["machine"]["context"]}, "activities": {}, "resources": {}, "journal": []} for row in rows]
        return {"configurations": configurations, "current": rows[-1]["state"] if rows else None, "journal": []}

    def view(self):
        value = super().view()
        value["layout_id"] = self.bo_layout_id
        machine = self.bo_machine()
        value["machine"]["configurations"] = machine["configurations"]
        value["instances"] = self.graph.bo_instances(machine)
        return value

    def export(self):
        return self.graph.bo_export(binding=self.binding(), runtime={"machine": self.bo_machine(), "events": self.current_events(), "runtime_frames": {"schema": "stategraph-runtime-frames/v1", "partial": True, "frames": [frame for frame, _ in self.frames.values()]}})

class BOIntegration:
    def __init__(self, root: Path, store, session, mode="on"):
        self.store, self.session, self.mode = store, session, mode
        self.lock = threading.RLock()
        self.policy_evaluations = deque(maxlen=1000)
        self.policy_roots = OrderedDict()
        def sink(value, kind):
            if mode == "fault":
                raise OSError("Explicit observer transport-failure test")
            return session.event(value) if kind == "events" else session.snapshot(value)
        self.probe = BOProbe(session.project, session.manifest["build_id"], enabled=mode != "off", sink=sink, capacity=512)
        config = json.loads((Path(root) / "bo_stategraph/databases.json").read_text(encoding="utf-8"))
        self.data = BODataRuntime(self.probe, config)
        self.data.attach_sqlalchemy(store.engine)
        store.bo_tx = lambda manager: self.data.transaction("db-transaction", manager)
        for method, node in (("user", "db-user"), ("list_users", "db-users"), ("file", "db-file"), ("grant", "db-grant"), ("list_files", "db-list"), ("add_file", "db-add-file"), ("share_file", "db-share"), ("revoke_file", "db-revoke"), ("active_recipients", "db-recipients"), ("snapshot", "db-snapshot")):
            original = getattr(store, method)
            setattr(store, method, self.wrap(original, node))

    def wrap(self, original, node):
        @wraps(original)
        def bo_observed(*args, **kwargs):
            with self.data.operation(node):
                return original(*args, **kwargs)
        return bo_observed

    def wire(self, service):
        original = service.public_file
        @wraps(original)
        def bo_transform(row):
            return self.data.transform("db-details-transform", original, row, before=lambda value: {"size": value["size"]}, after=lambda value: {"size": value["size"]})
        service.public_file = bo_transform
        service.bo_sink = self.emit
        service.bo_policy_sink = self.record_policy

    def record_policy(self, evaluation, file_id):
        with self.lock:
            self.policy_evaluations.append(deepcopy(evaluation))
            emitted = record_evaluation(self.session.model["policy"], evaluation, self.probe, entity=file_id, attempt="file-lifecycle")
            self.policy_roots[evaluation["check_id"]] = emitted.get(evaluation["root"])
            if len(self.policy_roots) > 1000:
                self.policy_roots.popitem(last=False)

    def emit(self, node, phase, inputs, outputs, row=None, transition=None):
        with self.lock:
            entity = row["id"] if row else inputs.get("file_id", "application")
            revision = row["revision"] if row else None
            root_event = self.policy_roots.get(inputs.get("bo_check")) if node == "policy-check" else None
            evidence = self.probe.record(node, phase, lambda: {"inputs": inputs, "outputs": outputs}, entity=entity, attempt="file-lifecycle" if entity != "application" else "application", scope="entity" if entity != "application" else "application", revision=revision, call_id=inputs["bo_check"] + ":business" if node == "policy-check" else None, depends=[{"event": root_event, "type": "data"}] if root_event else [])
            if row and evidence:
                with bo_internal():
                    raw = next(item for item in self.store.snapshot()["files"] if item["id"] == row["id"])
                context = {key: raw[key] for key in self.session.model["machine"]["context"]}
                self.probe.snapshot(row["id"], raw["state"], context, raw["revision"], evidence, event=transition["event"] if transition else None, guards=transition["guards"] if transition else {}, payload=transition["payload"] if transition else {})

    def close(self):
        self.probe.flush(5)
        self.probe.close()
        self.data.close()

